import{resolveDevelopmentStateDirectory}from"#internal/application/dev-environment.js";import{join,relative}from"node:path";function resolveLocalWorkflowWorldDataDirectory(e){return join(resolveDevelopmentStateDirectory(e),`.workflow-data`)}function displayLocalWorkflowWorldDataDirectory(e){return relative(e,resolveLocalWorkflowWorldDataDirectory(e)).replaceAll(`\\`,`/`)}export{displayLocalWorkflowWorldDataDirectory,resolveLocalWorkflowWorldDataDirectory};